#!/usr/bin/env node
const fs = require("node:fs");
const path = require("node:path");
function exportReport(format, output) {
  const target = output || "./out.txt";
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, "report:" + format);
  return target;
}
module.exports = { exportReport };
